# name: two_example_dip
# description: Yes-rate on 2-example sets minus the mean yes-rate on 3- and 4-example sets; observed < null means people are more conservative on two-example sets (relative to larger sets) than the model's monotone capacity limit predicts.
def test_statistic(df):
    n = df["number_set"].str.count(",").to_numpy() + 1
    r = df["rating"].astype(float).to_numpy()
    a = r[n == 2]; b = r[n >= 3]
    if len(a) == 0 or len(b) == 0:
        return 0.0
    return float(a.mean() - b.mean())

# name: lag1_response_repetition
# description: Proportion of consecutive trials (same participant, trial_index increasing by 1) with the same response as the previous trial; observed > null means people perseverate on their previous answer beyond what stimulus-driven model predictions produce.
def test_statistic(df):
    ti = df["trial_index"].to_numpy()
    r = df["rating"].astype(int).to_numpy()
    cons = np.diff(ti) == 1
    if cons.sum() == 0:
        return 0.0
    return float((r[1:] == r[:-1])[cons].mean())

# name: late_minus_early_yes_rate
# description: Yes-rate on trials with trial_index >= 225 minus yes-rate on trials with trial_index < 225; observed differing from null means a drift in yes-bias across the session that the stationary model does not capture (observed < null: people become more conservative over time).
def test_statistic(df):
    ti = df["trial_index"].to_numpy()
    r = df["rating"].astype(float).to_numpy()
    late = ti >= 225
    if late.sum() == 0 or (~late).sum() == 0:
        return 0.0
    return float(r[late].mean() - r[~late].mean())
